1	package tariff
2	
3	import (
4		"errors"
5		"math"
6		"testing"
7	)
8	
9	// TestItemOutcomesListsConfirmationsAndRejections 覆盖按费率项查看已受理报价的
10	// 核心场景：确认与拒绝都列出；旧版确认价不被当前费率重算；
11	// 失效后引用旧版的拒绝与旧确认同时保留；排序按首次受理时刻、再按请求标识。
12	func TestItemOutcomesListsConfirmationsAndRejections(t *testing.T) {
13		now, setNow := fixedClock(at(1))
14		b := NewBook(WithClock(now))
15		mustReg := func(r RegisterRequest) {
16			t.Helper()
17			if err := b.RegisterVersion(r); err != nil {
18				t.Fatalf("register %+v: %v", r, err)
19			}
20		}
21		mustReg(RegisterRequest{ItemID: "seat", VersionID: "seat-v1", UnitPrice: 150, Start: at(0), End: atPtr(100)})
22		mustReg(RegisterRequest{ItemID: "seat", VersionID: "seat-v2", UnitPrice: 180, Start: at(10), Replaces: "seat-v1"})
23	
24		// ① 旧版按 150 分、数量 4 确认 600 分。
25		setNow(at(2))
26		confirmed, err := b.Quote(QuoteRequest{RequestID: "q-old-confirmed", ItemID: "seat", VersionID: "seat-v1", Quantity: 4})
27		if err != nil || !confirmed.Confirmed {
28			t.Fatalf("confirmed quote: %v %+v", err, confirmed)
29		}
30	
31		// 交接后新请求引用旧版，因失效被拒绝（零金额不是免费确认价）。
32		setNow(at(20))
33		expired, err := b.Quote(QuoteRequest{RequestID: "q-old-expired", ItemID: "seat", VersionID: "seat-v1", Quantity: 4})
34		if err != nil {
35			t.Fatal(err)
36		}
37		if expired.Confirmed || expired.Reason != ReasonVersionExpired {
38			t.Fatalf("want version_expired rejection: %+v", expired)
39		}
40	
41		// 交接后引用新版的确认也应一并列出（受理时刻更晚）。
42		setNow(at(21))
43		newConfirmed, err := b.Quote(QuoteRequest{RequestID: "q-new-confirmed", ItemID: "seat", VersionID: "seat-v2", Quantity: 4})
44		if err != nil || !newConfirmed.Confirmed || newConfirmed.UnitPrice != 180 || newConfirmed.Total != 720 {
45			t.Fatalf("new confirmed: %v %+v", err, newConfirmed)
46		}
47	
48		got, err := b.ItemOutcomes("seat")
49		if err != nil {
50			t.Fatal(err)
51		}
52		if len(got) != 3 {
53			t.Fatalf("want 3 outcomes, got %d: %+v", len(got), got)
54		}
55	
56		// 按首次受理时刻从早到晚排列。
57		wantOrder := []string{"q-old-confirmed", "q-old-expired", "q-new-confirmed"}
58		for i, id := range wantOrder {
59			if got[i].Request.RequestID != id {
60				t.Fatalf("position %d: want %s, got %s (full: %v)", i, id, got[i].Request.RequestID, requestIDs(got))
61			}
62		}
63	
64		old := got[0]
65		if !old.Confirmed || old.Request.VersionID != "seat-v1" || old.Request.Quantity != 4 ||
66			old.UnitPrice != 150 || old.Total != 600 || old.Reason != ReasonNone ||
